  const current = jobs.get(job_id);
  if (current === 'running') {
    const err = new Error(`Job ${job_id} is already running`);
    err.code = -32602;
    throw err;
  }
  jobs.set(job_id, 'running');
  return { content: [{ type: 'text', text: JSON.stringify({ job_id, status: 'running' }) }] };
